"""
Turning a trained classifier's JSON into the actual embedded resource.
"""
from __future__ import annotations

from pathlib import Path

RESOURCES_HPP_TEMPLATE = '''#ifndef FLOWER_EVOLVER_RESOURCES_HPP
#define FLOWER_EVOLVER_RESOURCES_HPP

#include <string>

namespace fe::resources{{
    /**
     *  @brief a SOM species classifier trained offline, embedded so that
     *  classification works with no classifier supplied. Plain JSON
     *  text, unlike the base64 binary in include/fe/3D/Resources.hpp.
     *
     *  Generated by som_trainer.export, from tools/train_som.ipynb or
     *  `tools/som.py --export` (see tools/README.md); do not edit by hand.
     */
    const std::string trainedSOM = "{trained_som_json}";
}} // namespace fe::resources

#endif // FLOWER_EVOLVER_RESOURCES_HPP
'''


def resources_hpp_text(classifier_json: str) -> str:
    """The text of include/fe/Resources.hpp with `classifier_json` embedded as
    fe::resources::trainedSOM. `classifier_json` should be compact (no
    embedded newlines) -- classifier.to_json() already produces this, this
    function doesn't re-compact it.

    Only escapes double-quotes and backslashes for embedding into a C++
    string literal; classifier.to_json()'s output has neither raw newlines
    nor non-ASCII bytes to worry about beyond that (it's JsonBox's own
    compact writer, same as everywhere else in this project).
    """
    escaped = classifier_json.replace("\\", "\\\\").replace('"', '\\"')
    return RESOURCES_HPP_TEMPLATE.format(trained_som_json=escaped)


def write_resources_hpp(classifier_json: str, output_path: str | Path) -> Path:
    """Writes `resources_hpp_text(classifier_json)` to `output_path`."""
    path = Path(output_path)
    path.write_text(resources_hpp_text(classifier_json))
    return path
